using System.Reflection;

namespace Acme.Ticketing.Domain.Framework;

public sealed record PageQuery(int Page, int PageSize, string? OrderBy, bool Descending);

public sealed record PagedList<T>(IReadOnlyList<T> Items, int PageNumber, int PageSize, int TotalCount);

/// <summary>Finds the simple properties (scalars) of an entity that a query can be ordered by.</summary>
public static class SortableProperties
{
    public static PropertyInfo? Resolve(Type entityType, string name) =>
        entityType.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .FirstOrDefault(p => p.GetIndexParameters().Length == 0
                                 && p.CanRead
                                 && IsSimple(p.PropertyType)
                                 && string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase));

    private static bool IsSimple(Type type)
    {
        type = Nullable.GetUnderlyingType(type) ?? type;
        return type.IsPrimitive || type.IsEnum
            || type == typeof(string) || type == typeof(Guid) || type == typeof(decimal)
            || type == typeof(DateTime) || type == typeof(DateTimeOffset);
    }
}
